// FullmacFirmware.hpp — FullMAC (brcmfmac) firmware + board nvram compiled into the kext.
// Needed for OpenCore injection, where the kext bundle's Resources are not reachable.
// Blobs come from FullmacFwArrays.cpp, generated by scripts/gen_fullmac_arrays.py from
// firmware/fullmac/*.bin (firmware) and *.txt (nvram); stem = file name without extension.
#ifndef FullmacFirmware_hpp
#define FullmacFirmware_hpp
#include <libkern/OSTypes.h>

struct FullmacBlob { const char *stem; const UInt8 *data; UInt32 len; };

// nullptr when no such blob is embedded.
const FullmacBlob *bcmc_fullmac_find_fw(const char *stem);
const FullmacBlob *bcmc_fullmac_find_nvram(const char *stem);
const FullmacBlob *bcmc_fullmac_find_clm(const char *stem);   // optional regulatory blob, stem == firmware stem
#endif
